import json, subprocess, sys
BASE = '483f016'
run = lambda *a: subprocess.run(a, capture_output=True, text=True, check=True).stdout
c = json.load(open('.agent/contracts/099.json'))
scope = {f['path'] for k in ('files_create', 'files_modify') for f in c['scope'][k]}
orchestrator_owned = {'.agent/contracts/099.json', '.agent/run_state.json', '.agent/feature_list_014.json'}
